(() => {
'use strict';

const $=id=>document.getElementById(id);
const canvas=$('space'),stats=$('stats'),phase=$('phase'),overviewButton=$('overview'),resetButton=$('reset'),mic=$('eiraMic'),
searchForm=$('search'),query=$('query'),panel=$('panel'),closePanel=$('closePanel'),nodeTitle=$('nodeTitle'),
nodeMeta=$('nodeMeta'),enterCluster=$('enterCluster'),notice=$('notice');
if(!canvas||!stats||!phase||!overviewButton||!resetButton||!searchForm||!query||!panel||!closePanel||!nodeTitle||!nodeMeta||!enterCluster||!notice)return;

const gl=canvas.getContext('webgl2',{alpha:true,antialias:true,preserveDrawingBuffer:false});
let overview=null,mode='overview',selectedCluster=null,nodes=[],fibers=[],nodeById=new Map(),clusterCenters=new Map();
let activity={active_neuron_ids:[],active_cluster_ids:[],events:[],sequence:0},yaw=-.18,pitch=-.03,zoom=1.03,drag=null,pinch=0,idleSince=performance.now(),topologyGeneration=0;
let pointBuffer=null,lineBuffer=null,hotLineBuffer=null,pointCount=0,lineCount=0,hotLineCount=0;
let motionNav=false,motionRequesting=false,motionBase=null,lastOrientation=null,motionForward=0,motionStrafe=0,camX=0,camY=0,camZ=0,lastFrame=performance.now();

const VERT=`#version 300 es
precision highp float;
in vec3 aPosition;in vec3 aColor;in float aSize;
uniform mat4 uProjection;uniform mat4 uModel;uniform float uTime;
out vec3 vColor;
void main(){vec3 p=aPosition;float breathe=1.0+0.012*sin(uTime*0.0016+aPosition.y*3.0+aPosition.x*2.0);p*=breathe;gl_Position=uProjection*uModel*vec4(p,1.0);gl_PointSize=aSize/max(.26,gl_Position.w);vColor=aColor;}`;
const POINT_FRAG=`#version 300 es
precision highp float;in vec3 vColor;out vec4 outColor;
void main(){vec2 p=gl_PointCoord*2.-1.;float d=dot(p,p);if(d>1.)discard;float halo=1.-smoothstep(.05,1.,d);float core=1.-smoothstep(0.,.09,d);outColor=vec4(vColor*(.72+3.2*core),.08+.92*halo);}`;
const LINE_FRAG=`#version 300 es
precision highp float;in vec3 vColor;out vec4 outColor;
void main(){outColor=vec4(vColor,.50);}`;

function showNotice(text,ms=4200){notice.textContent=String(text||'');notice.classList.add('show');if(ms)setTimeout(()=>notice.classList.remove('show'),ms)}
function shader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(s)||'shader_compile_failed');return s}
function makeProgram(fragment){const p=gl.createProgram();gl.attachShader(p,shader(gl.VERTEX_SHADER,VERT));gl.attachShader(p,shader(gl.FRAGMENT_SHADER,fragment));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(p)||'program_link_failed');return p}
let pointProgram=null,lineProgram=null;
if(gl){try{pointProgram=makeProgram(POINT_FRAG);lineProgram=makeProgram(LINE_FRAG)}catch(error){showNotice(`NEURAL VISUALIZATION ERROR: ${error.message||error}`,0)}}else showNotice('WebGL2 is unavailable. Voice and text remain usable.',0);

function hash(text){let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function activeSet(){
 const ids=mode==='overview'?(activity.active_cluster_ids||[]):[...(activity.active_neuron_ids||[]),...(activity.active_cluster_ids||[])];
 return new Set(ids);
}
function colorFor(node,hot=false){
 if(hot)return[1,.88,.28];if(node.spine)return[.24,1,.78];
 switch(node.activity_class){case'runtime':return[.18,.84,1];case'state':return[.70,.38,1];case'artifact':return[1,.38,.84];case'secret_reference':return[1,.54,.28];case'external_dependency':return[.45,.61,.68];default:return node.hemisphere==='left'?[.18,.66,1]:node.hemisphere==='right'?[.72,.30,1]:[.24,1,.78]}
}
function anatomicalCenters(){
 clusterCenters.clear();if(!overview)return;
 const rows=[...(overview.clusters||[])].sort((a,b)=>String(a.cluster).localeCompare(String(b.cluster)));
 const left=rows.filter(r=>r.hemisphere==='left'&&!r.spine),right=rows.filter(r=>r.hemisphere==='right'&&!r.spine);
 const mid=rows.filter(r=>r.spine||r.hemisphere==='midline'||(!left.includes(r)&&!right.includes(r)));
 const place=(list,side)=>{
   const bands=Math.max(1,Math.ceil(Math.sqrt(list.length||1)));
   list.forEach((row,i)=>{
     const lane=i%bands,rowIndex=Math.floor(i/bands),rowCount=Math.max(1,Math.ceil(list.length/bands));
     const y=.76-(rowCount===1?0:rowIndex/(rowCount-1))*1.34;
     const lateral=.47+(lane/Math.max(1,bands-1))*.47;
     const z=(lane-(bands-1)/2)*.23;
     clusterCenters.set(row.cluster,[side*lateral,y,z]);
   });
 };
 place(left,-1);place(right,1);
 mid.forEach((row,i)=>{const n=Math.max(1,mid.length-1),t=mid.length===1?.5:i/n;clusterCenters.set(row.cluster,[0,.80-t*1.78,-.02])});
}
function clusterNodes(){return(overview?.clusters||[]).map(c=>({id:c.id,kind:'cluster',cluster:c.cluster,logical_path:c.cluster,hemisphere:c.hemisphere,spine:c.spine,activity_class:'cluster',neuron_count:c.neuron_count,file_count:c.file_count,code_count:c.code_count,synthetic:true}))}
function branchKey(node){if(node.spine||node.hemisphere==='midline')return'midline';return`${node.hemisphere||'midline'}:${node.activity_class||'other'}`}
function prepareHierarchy(list){
 const real=list.filter(n=>n.kind!=='cluster').sort((a,b)=>String(a.id).localeCompare(String(b.id))),groups=new Map();
 for(const n of real){const key=branchKey(n);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(n)}
 const keys=[...groups.keys()].sort();
 keys.forEach((key,branch)=>{const group=groups.get(key)||[];group.forEach((n,rank)=>{n._branch=branch;n._branchCount=keys.length;n._rank=rank;n._rankCount=group.length})});
}
function positionNode(node,expanded=false){
 if(node.kind==='cluster')return expanded?[0,0,0]:(clusterCenters.get(node.cluster)||[0,0,0]);
 const center=expanded?[0,0,0]:(clusterCenters.get(node.cluster)||[0,0,0]);
 const branch=Number(node._branch||0),branchCount=Math.max(1,Number(node._branchCount||1)),rank=Number(node._rank||0),rankCount=Math.max(1,Number(node._rankCount||1));
 const rankT=rankCount===1?.5:rank/(rankCount-1),branchT=branchCount===1?.5:branch/(branchCount-1);
 const side=node.spine||node.hemisphere==='midline'?0:node.hemisphere==='left'?-1:1;
 if(!expanded){return[center[0]+side*(.018+.050*branchT),center[1]+(rankT-.5)*.18,center[2]+(branchT-.5)*.14]}
 if(side===0)return[0,.66-rankT*1.32,(branchT-.5)*.10];
 return[side*(.23+.62*branchT),.62-rankT*1.24,(branchT-.5)*.72+(rank%2?-.025:.025)];
}
function setGraph(nextNodes,nextFibers,expanded=false){nodes=nextNodes;fibers=nextFibers||[];nodeById=new Map(nodes.map(n=>[n.id,n]));prepareHierarchy(nodes);for(const n of nodes)n.p=positionNode(n,expanded);rebuildBuffers();updateStats()}
function phaseText(){const count=(activity.active_cluster_ids||[]).length;if(count)return`<span class="liveDot"></span> LIVE EXECUTION • ${count} REGION${count===1?'':'S'} ACTIVE`;return`<span class="liveDot"></span> ${motionNav?'IPHONE MOTION INSIDE LIVE NEURAL ORGANISM':'LIVE NEURAL ORGANISM'}`}
function overviewGraph(){mode='overview';selectedCluster=null;setGraph(clusterNodes(),[],false);overviewButton.classList.add('active');phase.innerHTML=phaseText()}
function updateStats(extra=''){if(!overview)return;const visible=nodes.filter(n=>n.kind!=='cluster').length,total=Number(overview.inventory_neuron_count||0),fiberTotal=Number(overview.conductive_fiber_count||0);stats.textContent=`${total.toLocaleString()} NEURONS • ${fiberTotal.toLocaleString()} EVIDENCED FIBERS${visible?` • ${visible.toLocaleString()} IN FOCUS`:''}${extra?` • ${extra}`:''}`}
function addVertex(out,p,c,size){out.push(p[0],p[1],p[2],c[0],c[1],c[2],size)}
function addLine(out,a,b,c){addVertex(out,a,c,1);addVertex(out,b,c,1)}
function structuralLines(out){
 if(mode==='overview'){
   const spine=nodes.filter(n=>n.kind==='cluster'&&n.spine).sort((a,b)=>b.p[1]-a.p[1]);
   for(let i=1;i<spine.length;i++)addLine(out,spine[i-1].p,spine[i].p,[.10,.40,.35]);
   for(const n of nodes){if(n.kind!=='cluster'||n.spine)continue;addLine(out,n.p,[0,n.p[1],-.02],[.055,.15,.24])}
   return;
 }
 const anchors=new Map();
 for(const n of nodes){if(n.kind==='cluster')continue;const key=branchKey(n);if(!anchors.has(key)){const side=n.spine||n.hemisphere==='midline'?0:n.hemisphere==='left'?-1:1;const bt=Number(n._branchCount||1)===1?.5:Number(n._branch||0)/Math.max(1,Number(n._branchCount||1)-1);const a=side===0?[0,0,(bt-.5)*.10]:[side*(.18+.38*bt),0,(bt-.5)*.48];anchors.set(key,a);addLine(out,[0,0,0],a,[.06,.18,.24])}addLine(out,anchors.get(key),n.p,[.055,.10,.16])}
}
function upload(buffer,data){if(!gl)return null;const b=buffer||gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,data,gl.DYNAMIC_DRAW);return b}
function rebuildBuffers(){
 if(!gl)return;const hot=activeSet(),points=[],lines=[],hotLines=[];
 for(const n of nodes){const isHot=hot.has(n.id),size=n.kind==='cluster'?(n.spine?17:19):(isHot?12:n.spine?7.5:4.8),color=colorFor(n,isHot);addVertex(points,n.p,color,size);if(isHot){addVertex(points,n.p,[1,1,.84],size*1.65);addVertex(points,n.p,color,size*2.6);addVertex(points,n.p,color,size*3.7)}}
 structuralLines(lines);
 for(const f of fibers){if(!f.conductive)continue;const a=nodeById.get(f.source),b=nodeById.get(f.target);if(!a?.p||!b?.p)continue;addLine(lines,a.p,b.p,[.10,.38,.54]);if(hot.has(f.source)||hot.has(f.target))addLine(hotLines,a.p,b.p,[.62,1,1])}
 const p=new Float32Array(points),l=new Float32Array(lines),h=new Float32Array(hotLines);pointCount=p.length/7;lineCount=l.length/7;hotLineCount=h.length/7;pointBuffer=upload(pointBuffer,p);lineBuffer=upload(lineBuffer,l);hotLineBuffer=upload(hotLineBuffer,h);
}
function identity(){const m=new Float32Array(16);m[0]=m[5]=m[10]=m[15]=1;return m}
function perspective(fov,aspect,near,far){const f=1/Math.tan(fov/2),m=new Float32Array(16);m[0]=f/aspect;m[5]=f;m[10]=(far+near)/(near-far);m[11]=-1;m[14]=(2*far*near)/(near-far);return m}
function modelMatrix(){const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch),s=zoom,m=identity();m[0]=cy*s;m[2]=-sy*s;m[4]=sy*sp*s;m[5]=cp*s;m[6]=cy*sp*s;m[8]=sy*cp*s;m[9]=-sp*s;m[10]=cy*cp*s;m[12]=-camX;m[13]=-camY;m[14]=-3.05+camZ;return m}
function draw(program,buffer,count,primitive,projection,model,t){if(!program||!buffer||!count)return;gl.useProgram(program);gl.bindBuffer(gl.ARRAY_BUFFER,buffer);const stride=7*4,p=gl.getAttribLocation(program,'aPosition'),c=gl.getAttribLocation(program,'aColor'),s=gl.getAttribLocation(program,'aSize');gl.enableVertexAttribArray(p);gl.vertexAttribPointer(p,3,gl.FLOAT,false,stride,0);gl.enableVertexAttribArray(c);gl.vertexAttribPointer(c,3,gl.FLOAT,false,stride,3*4);gl.enableVertexAttribArray(s);gl.vertexAttribPointer(s,1,gl.FLOAT,false,stride,6*4);gl.uniformMatrix4fv(gl.getUniformLocation(program,'uProjection'),false,projection);gl.uniformMatrix4fv(gl.getUniformLocation(program,'uModel'),false,model);gl.uniform1f(gl.getUniformLocation(program,'uTime'),t);gl.drawArrays(primitive,0,count)}
function particleData(t){const hot=activeSet(),out=[];for(const f of fibers){if(!f.conductive||(!hot.has(f.source)&&!hot.has(f.target)))continue;const a=nodeById.get(f.source),b=nodeById.get(f.target);if(!a?.p||!b?.p)continue;const seed=(hash(f.source+f.target)%1000)/1000;for(let k=0;k<3;k++){const q=(t*.00046+seed+k/3)%1;addVertex(out,[a.p[0]+(b.p[0]-a.p[0])*q,a.p[1]+(b.p[1]-a.p[1])*q,a.p[2]+(b.p[2]-a.p[2])*q],[1,.92,.50],11)}}return new Float32Array(out)}
function wrapDegrees(value){let v=value;while(v>180)v-=360;while(v<-180)v+=360;return v}
function clamp(value,min,max){return Math.max(min,Math.min(max,value))}
function deadzone(value,zone){if(Math.abs(value)<=zone)return 0;return Math.sign(value)*(Math.abs(value)-zone)/(1-zone)}
function onOrientation(event){if(event.alpha==null||event.beta==null||event.gamma==null)return;lastOrientation={alpha:Number(event.alpha),beta:Number(event.beta),gamma:Number(event.gamma)};if(!motionNav)return;if(!motionBase){motionBase={...lastOrientation};return}const da=wrapDegrees(lastOrientation.alpha-motionBase.alpha),db=lastOrientation.beta-motionBase.beta,dg=lastOrientation.gamma-motionBase.gamma;yaw=-.18-da*Math.PI/180;pitch=clamp(-.03-db*Math.PI/360,-1.05,1.05);motionForward=deadzone(clamp(-db/28,-1,1),.13);motionStrafe=deadzone(clamp(dg/24,-1,1),.16);idleSince=performance.now()}
async function enableMotionNavigation(){if(motionNav||motionRequesting||typeof DeviceOrientationEvent==='undefined')return;motionRequesting=true;try{if(typeof DeviceOrientationEvent.requestPermission==='function'){const permission=await DeviceOrientationEvent.requestPermission();if(permission!=='granted')return}motionNav=true;motionBase=null;window.addEventListener('deviceorientation',onOrientation,true);phase.innerHTML=phaseText();showNotice('IPHONE MOTION ACTIVE — turn to look; tilt to move through the live EIRA 2 neural space.',3200)}catch(error){showNotice(`IPHONE MOTION UNAVAILABLE: ${error.message||error}`,4200)}finally{motionRequesting=false}}
function advanceMotion(t){const dt=Math.min(.05,Math.max(0,(t-lastFrame)/1000));lastFrame=t;if(!motionNav)return;const speed=.82*dt,forward=motionForward*speed,strafe=motionStrafe*speed;camX=clamp(camX+Math.sin(yaw)*forward+Math.cos(yaw)*strafe,-3.2,3.2);camZ=clamp(camZ+Math.cos(yaw)*forward-Math.sin(yaw)*strafe,-2.0,6.2)}
function render(t){if(!gl||!pointProgram||!lineProgram)return;advanceMotion(t);if(!motionNav&&performance.now()-idleSince>2500&&!drag)yaw+=.00048;const d=Math.min(devicePixelRatio||1,2),w=Math.max(1,innerWidth),h=Math.max(1,innerHeight);if(canvas.width!==Math.floor(w*d)||canvas.height!==Math.floor(h*d)){canvas.width=Math.floor(w*d);canvas.height=Math.floor(h*d)}gl.viewport(0,0,canvas.width,canvas.height);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE);gl.enable(gl.DEPTH_TEST);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);const projection=perspective(Math.PI/3,w/h,.03,50),model=modelMatrix();draw(lineProgram,lineBuffer,lineCount,gl.LINES,projection,model,t);draw(lineProgram,hotLineBuffer,hotLineCount,gl.LINES,projection,model,t);draw(pointProgram,pointBuffer,pointCount,gl.POINTS,projection,model,t);const particles=particleData(t);if(particles.length){const b=upload(null,particles);draw(pointProgram,b,particles.length/7,gl.POINTS,projection,model,t);gl.deleteBuffer(b)}requestAnimationFrame(render)}
async function json(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`${r.status} ${url}`);return r.json()}
async function loadOverview(){overview=await json('/api/neural/overview');topologyGeneration=Number(overview.topology_generation||0);anatomicalCenters();overviewGraph()}
async function loadCluster(cluster){mode='cluster';selectedCluster=cluster;overviewButton.classList.remove('active');phase.innerHTML=`<span class="liveDot"></span> REGION ${String(cluster).toUpperCase()}`;const page=await json(`/api/neural/nodes?cluster=${encodeURIComponent(cluster)}&cursor=0&limit=1200&paths=0`),edgeData=await json(`/api/neural/fibers?cluster=${encodeURIComponent(cluster)}&limit=12000`),clusterNode=clusterNodes().filter(n=>n.cluster===cluster);setGraph([...clusterNode,...(page.neurons||[])],edgeData.fibers||[],true);updateStats(page.total>page.neurons.length?`${page.neurons.length.toLocaleString()} OF ${Number(page.total).toLocaleString()} SHOWN`:'REGION COMPLETE')}
function openNode(node){if(!node)return;nodeTitle.textContent=node.cluster||node.logical_path||node.id||'Neural region';const bits=[];if(node.kind==='cluster'){bits.push(`${Number(node.neuron_count||0).toLocaleString()} neurons`);if(node.file_count!=null)bits.push(`${Number(node.file_count).toLocaleString()} files`);if(node.code_count!=null)bits.push(`${Number(node.code_count).toLocaleString()} code nodes`)}else{if(node.logical_path)bits.push(String(node.logical_path));if(node.activity_class)bits.push(`class: ${node.activity_class}`);if(node.hemisphere)bits.push(`hemisphere: ${node.hemisphere}`)}nodeMeta.textContent=bits.join('\n');enterCluster.hidden=node.kind!=='cluster';enterCluster.dataset.cluster=node.cluster||'';panel.classList.add('open')}
async function search(term){const clean=String(term||'').trim();if(!clean)return;const data=await json(`/api/neural/search?q=${encodeURIComponent(clean)}&limit=24`),rows=data.matches||data.results||data.neurons||[];if(!rows.length){showNotice(`No EIRA2 neural match for “${clean}”.`);return}const row=rows[0];if(row.cluster&&mode!=='cluster')await loadCluster(row.cluster);openNode(nodeById.get(row.id)||row)}
function projectNode(node){const p=node.p;if(!p)return null;const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch),s=zoom,x=(cy*p[0]+sy*sp*p[1]+sy*cp*p[2])*s-camX,y=(cp*p[1]-sp*p[2])*s-camY,z=(-sy*p[0]+cy*sp*p[1]+cy*cp*p[2])*s-3.05+camZ;if(z>=-.05)return null;const aspect=innerWidth/Math.max(1,innerHeight),f=1/Math.tan(Math.PI/6);return[innerWidth*(.5+(x*f/aspect/-z)*.5),innerHeight*(.5-(y*f/-z)*.5),-z]}
function pick(clientX,clientY){let best=null,bestD=Infinity;for(const n of nodes){const p=projectNode(n);if(!p)continue;const d=Math.hypot(p[0]-clientX,p[1]-clientY),radius=n.kind==='cluster'?30:15;if(d<radius&&d<bestD){best=n;bestD=d}}return best}
function resetView(){yaw=-.18;pitch=-.03;zoom=1.03;camX=camY=camZ=0;motionForward=motionStrafe=0;motionBase=lastOrientation?{...lastOrientation}:null;idleSince=performance.now();panel.classList.remove('open');if(mode!=='overview')overviewGraph()}
canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,moved:false};idleSince=performance.now();canvas.setPointerCapture?.(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag||motionNav)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>3)drag.moved=true;yaw+=dx*.006;pitch=Math.max(-1.05,Math.min(1.05,pitch+dy*.005));drag.x=e.clientX;drag.y=e.clientY;idleSince=performance.now()});canvas.addEventListener('pointerup',e=>{if(drag&&!drag.moved){const n=pick(e.clientX,e.clientY);if(n)openNode(n)}drag=null;idleSince=performance.now()});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.55,Math.min(2.25,zoom*(e.deltaY>0?.92:1.08)));idleSince=performance.now()},{passive:false});canvas.addEventListener('touchstart',e=>{if(e.touches.length===2)pinch=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY)},{passive:true});canvas.addEventListener('touchmove',e=>{if(e.touches.length===2&&pinch&&!motionNav){const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);zoom=Math.max(.55,Math.min(2.25,zoom*(d/pinch)));pinch=d;idleSince=performance.now()}},{passive:true});canvas.addEventListener('touchend',()=>{pinch=0},{passive:true});
if(mic)mic.addEventListener('click',()=>{enableMotionNavigation()});overviewButton.addEventListener('click',overviewGraph);resetButton.addEventListener('click',resetView);searchForm.addEventListener('submit',e=>{e.preventDefault();search(query.value).catch(err=>showNotice(`SEARCH ERROR: ${err.message||err}`))});closePanel.addEventListener('click',()=>panel.classList.remove('open'));enterCluster.addEventListener('click',()=>{const c=enterCluster.dataset.cluster;if(c)loadCluster(c).catch(err=>showNotice(`REGION ERROR: ${err.message||err}`))});
async function pollActivity(){try{const next=await json('/api/neural/activity?window=2.8&limit=240');if(Number(next.sequence||0)!==Number(activity.sequence||0)){activity=next;rebuildBuffers();if(mode==='overview')phase.innerHTML=phaseText()}}catch(_){}setTimeout(pollActivity,650)}
async function pollTopology(){try{const next=await json('/api/neural/overview');if(Number(next.topology_generation||0)!==topologyGeneration){overview=next;topologyGeneration=Number(next.topology_generation||0);anatomicalCenters();if(mode==='overview')overviewGraph();else updateStats('TOPOLOGY UPDATED')}}catch(_){}setTimeout(pollTopology,4000)}
loadOverview().then(()=>{pollActivity();pollTopology();if(gl)requestAnimationFrame(render)}).catch(error=>showNotice(`NEURAL START ERROR: ${error.message||error}`,0));
})();

'use strict';

const $ = s => document.querySelector(s);
const log = $('#log');
const canvas = $('#brain');
const ctx = canvas.getContext('2d');

let state = {active:false, muted:false};
let mic = null, audioCtx = null, analyser = null, vadRAF = 0;
let pcmNode = null, pcmFrames = [], voiceBusy = false, speechFrames = 0, silenceSince = 0, recordStarted = 0, cooldownUntil = 0;
let neural = {nodes:[], fibers:[], activity:[]};
let topology = {graph:new Map(), cores:[], activity:new Map(), pathEdges:new Set(), pathNodes:new Map(), canonical:new Set(), routes:[]};
let screenNodes = [], selectedId = null, drag = null;
let rot = {x:-0.08, y:0.18};
let autoAngle = 0;

const CORE_VALUES = new Set(['core','kernel','supervisor','spine','registry','orchestrator','brain_core','neural_core','system_core']);
const CORE_ID_RE = /(?:^|[._:\/-])(core|kernel|supervisor|spine)(?:$|[._:\/-])/i;
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function add(w,t,k='eira'){
  const p=document.createElement('p');
  p.className='msg '+k;
  p.innerHTML=`<span class="who">${esc(w)}</span>${esc(t)}`;
  log.appendChild(p); log.scrollTop=log.scrollHeight;
}

async function req(u,o={}){
  const r=await fetch(u,{cache:'no-store',...o}); let j={};
  try{j=await r.json()}catch{}
  if(!r.ok) throw Error(j.error||`${r.status} ${r.statusText}`);
  return j;
}

function updateState(){
  const label=!state.active?'INACTIVE':state.muted?'MUTED':voiceBusy?'TRANSCRIBING':'LISTENING';
  $('#activePill').textContent=label;
